package dev.pedro.learning.ecommerce.payment.application;
import dev.pedro.learning.ecommerce.payment.domain.*;import dev.pedro.learning.ecommerce.payment.event.*;import dev.pedro.learning.ecommerce.payment.inbox.*;import dev.pedro.learning.ecommerce.payment.outbox.OutboxWriter;import dev.pedro.learning.ecommerce.payment.provider.*;import jakarta.enterprise.context.ApplicationScoped;import jakarta.transaction.Transactional;import org.jboss.logging.Logger;import org.jboss.logging.MDC;import java.time.Instant;import java.util.UUID;
@ApplicationScoped public class PaymentSagaService{private static final Logger LOG=Logger.getLogger(PaymentSagaService.class);private final PaymentRepository payments;private final InboxEventRepository inbox;private final OutboxWriter outbox;private final PaymentProviderGateway gateway;public PaymentSagaService(PaymentRepository payments,InboxEventRepository inbox,OutboxWriter outbox,PaymentProviderGateway gateway){this.payments=payments;this.inbox=inbox;this.outbox=outbox;this.gateway=gateway;}
 @Transactional public void onStockReserved(EventEnvelope<StockReservedPayload> event){MDC.put("correlationId",event.correlationId().toString());try{if(inbox.findById(event.eventId())!=null){LOG.info("[PAYMENT] Duplicate StockReserved ignored");return;}InboxEvent in=new InboxEvent();in.eventId=event.eventId();in.eventType=event.eventType();in.receivedAt=Instant.now();inbox.persist(in);PaymentEntity existing=payments.findByOrderId(event.payload().orderId());if(existing!=null){in.processedAt=Instant.now();LOG.info("[PAYMENT] Order already has payment result");return;}
  UUID paymentId=UUID.randomUUID();ProviderPaymentResponse provider=gateway.pay(new ProviderPaymentRequest(event.payload().orderId(),event.payload().totalAmount(),event.eventId().toString()));PaymentEntity payment=new PaymentEntity();payment.id=paymentId;payment.orderId=event.payload().orderId();payment.amount=event.payload().totalAmount();payment.createdAt=Instant.now();
  if(provider.success()){payment.status=PaymentStatus.COMPLETED;payment.providerReference=provider.providerReference();payments.persist(payment);var completed=new EventEnvelope<>(UUID.randomUUID(),event.correlationId(),"PaymentCompleted",Instant.now(),1,new PaymentCompletedPayload(payment.orderId,payment.id,payment.providerReference));outbox.append("payment-events",payment.orderId.toString(),completed);LOG.info("[PAYMENT] PaymentCompleted");}
  else{payment.status=PaymentStatus.FAILED;payment.failureReason=provider.message();payments.persist(payment);var failed=new EventEnvelope<>(UUID.randomUUID(),event.correlationId(),"PaymentFailed",Instant.now(),1,new PaymentFailedPayload(payment.orderId,payment.id,payment.failureReason));outbox.append("payment-events",payment.orderId.toString(),failed);LOG.info("[PAYMENT] PaymentFailed");}in.processedAt=Instant.now();}finally{MDC.remove("correlationId");}}
}